// The root of the Product aggregate: its state changes only through its methods, which check its rules (HS007).
public sealed class Product : IAggregateRoot
{
    private readonly List<IDomainEvent> _domainEvents = [];

    private Product(ProductId id)
    {
        Id = id;
    }

    // Rehydration only: persistence restores the state of the stored aggregate. Business code calls Create.
    private Product()
    {
    }

    public ProductId Id { get; }

    // Events raised and not yet published. Not persisted: a reloaded aggregate has none.
    public IReadOnlyList<IDomainEvent> DomainEvents => _domainEvents.AsReadOnly();

    // Creates the aggregate once its rules hold. Name it after the business fact, such as Booking.Confirm, take the state of
    // the new aggregate as parameters, and throw a DomainException, or a ConflictException, for each rule they break.
    public static Product Create() => new(ProductId.New());

    public IReadOnlyList<IDomainEvent> DequeueDomainEvents()
    {
        var domainEvents = _domainEvents.ToArray();
        _domainEvents.Clear();
        return domainEvents;
    }
